// Test: Darf der Code-Node Dateien im Vault lesen und schreiben?
const fs = require('fs');
const path = require('path');
const dir = '/vault/Finanzen/Trading/System/Automation/status-state';
fs.mkdirSync(dir, { recursive: true });
const f = path.join(dir, '_fs-test.json');
fs.writeFileSync(f + '.tmp', JSON.stringify({ ok: true, at: new Date().toISOString() }));
fs.renameSync(f + '.tmp', f);
const content = JSON.parse(fs.readFileSync(f, 'utf8'));
fs.unlinkSync(f);
return [{ json: { ergebnis: 'Dateizugriff funktioniert', gelesen: content, trading_ordner: fs.readdirSync('/vault/Finanzen/Trading') } }];
